mapper.select:
SELECT
bo.org_id as orgId,
bo.abbreviation,
IFNULL( btp.firstVisitPerNum, 0 ) AS firstVisitPerNum,
IFNULL( btp1.repeatVisitsPerNum, 0 ) AS repeatVisitsPerNum,
IFNULL( btp1.repeatVisitsPerTimes, 0 ) AS repeatVisitsPerTimes,
IFNULL( btp2.treatPerTimes, 0 ) AS treatPerTimes,
IFNULL( btp2.treatPerNum, 0 ) AS treatPerNum,
IFNULL( btp3.appointPerNum, 0 ) AS appointPerNum,
IFNULL( btp3.appointPerTimes, 0 ) AS appointPerTimes,
IFNULL( btp4.appointModifyPerTimes, 0 ) AS appointModifyPerTimes,
IFNULL( btp5.appointCancelPerTimes, 0 ) AS appointCancelPerTimes,
IFNULL( btp6.appointMissedPerTimes, 0 ) AS appointMissedPerTimes,
IFNULL( bb.totalActualAmount, 0 ) AS totalActualAmount
FROM
base_organization bo
LEFT JOIN (
SELECT
btp.org_id,
COUNT( DISTINCT btp.patient_id ) AS firstVisitPerNum
FROM
base_treatment_process btp

    AND btp.treat_end_time IS NOT NULL
    AND btp.treat_type = 0

        AND btp.org_id IN

            #{item}




            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d') >= #{query.startDate}


            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d') <= #{query.endDate}




            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m') >= #{query.startDate}


            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m') <= #{query.endDate}




            AND DATE_FORMAT( btp.treat_start_time, '%Y') >= #{query.startDate}


            AND DATE_FORMAT( btp.treat_start_time, '%Y') <= #{query.endDate}



GROUP BY
btp.org_id
) btp ON bo.org_id = btp.org_id
LEFT JOIN (
SELECT
btp.org_id,
COUNT( DISTINCT btp.patient_id ) AS repeatVisitsPerNum,
COUNT( btp.treatment_id ) AS repeatVisitsPerTimes
FROM
base_treatment_process btp

    AND btp.treat_end_time IS NOT NULL
    AND btp.treat_type = 1

        AND btp.org_id IN

            #{item}




            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d') >= #{query.startDate}


            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d') <= #{query.endDate}




            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m') >= #{query.startDate}


            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m') <= #{query.endDate}




            AND DATE_FORMAT( btp.treat_start_time, '%Y') >= #{query.startDate}


            AND DATE_FORMAT( btp.treat_start_time, '%Y') <= #{query.endDate}



GROUP BY
btp.org_id
) btp1 ON bo.org_id = btp1.org_id
LEFT JOIN (
SELECT
btp.org_id,
COUNT( DISTINCT btp.patient_id ) AS treatPerNum,
COUNT( btp.treatment_id ) AS treatPerTimes
FROM
base_treatment_process btp

    AND btp.treat_end_time IS NOT NULL

        AND btp.org_id IN

            #{item}




            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d') >= #{query.startDate}


            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m-%d') <= #{query.endDate}




            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m') >= #{query.startDate}


            AND DATE_FORMAT( btp.treat_start_time, '%Y-%m') <= #{query.endDate}




            AND DATE_FORMAT( btp.treat_start_time, '%Y') >= #{query.startDate}


            AND DATE_FORMAT( btp.treat_start_time, '%Y') <= #{query.endDate}



GROUP BY
btp.org_id
) btp2 ON bo.org_id = btp2.org_id
LEFT JOIN (
SELECT
btp.org_id,
COUNT( DISTINCT btp.patient_id ) AS appointPerNum,
COUNT( btp.appointment_id ) AS appointPerTimes
FROM
base_treatment_process btp

    AND btp.appointment_id IS NOT NULL
    AND btp.appoint_status != 2

        AND btp.org_id IN

            #{item}




            AND DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d') >= #{query.startDate}


            AND DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d') <= #{query.endDate}




            AND DATE_FORMAT( btp.appoint_start_time, '%Y-%m') >= #{query.startDate}


            AND DATE_FORMAT( btp.appoint_start_time, '%Y-%m') <= #{query.endDate}




            AND DATE_FORMAT( btp.appoint_start_time, '%Y') >= #{query.startDate}


            AND DATE_FORMAT( btp.appoint_start_time, '%Y') <= #{query.endDate}



GROUP BY
btp.org_id
) btp3 ON bo.org_id = btp3.org_id
LEFT JOIN (
SELECT
btp.org_id,
SUM( btp.appoint_modify_time ) AS appointModifyPerTimes
FROM
base_treatment_process btp

    AND btp.appointment_id IS NOT NULL
    AND btp.appoint_modify_time > 0

        AND btp.org_id IN

            #{item}




            AND DATE_FORMAT( btp.appointment_crt_time, '%Y-%m-%d') >= #{query.startDate}


            AND DATE_FORMAT( btp.appointment_crt_time, '%Y-%m-%d') <= #{query.endDate}




            AND DATE_FORMAT( btp.appointment_crt_time, '%Y-%m') >= #{query.startDate}


            AND DATE_FORMAT( btp.appointment_crt_time, '%Y-%m') <= #{query.endDate}




            AND DATE_FORMAT( btp.appointment_crt_time, '%Y') >= #{query.startDate}


            AND DATE_FORMAT( btp.appointment_crt_time, '%Y') <= #{query.endDate}



GROUP BY
btp.org_id
) btp4 ON bo.org_id = btp4.org_id
LEFT JOIN (
SELECT
btp.org_id,
COUNT( btp.appointment_id ) AS appointCancelPerTimes
FROM
base_treatment_process btp

    AND btp.appointment_id IS NOT NULL
    AND btp.appoint_status = 2

        AND btp.org_id IN

            #{item}




            AND DATE_FORMAT( btp.appointment_crt_time, '%Y-%m-%d') >= #{query.startDate}


            AND DATE_FORMAT( btp.appointment_crt_time, '%Y-%m-%d') <= #{query.endDate}




            AND DATE_FORMAT( btp.appointment_crt_time, '%Y-%m') >= #{query.startDate}


            AND DATE_FORMAT( btp.appointment_crt_time, '%Y-%m') <= #{query.endDate}




            AND DATE_FORMAT( btp.appointment_crt_time, '%Y') >= #{query.startDate}


            AND DATE_FORMAT( btp.appointment_crt_time, '%Y') <= #{query.endDate}



GROUP BY
btp.org_id
) btp5 ON bo.org_id = btp5.org_id
LEFT JOIN (
SELECT
btp.org_id,
COUNT( appointment_id ) AS appointMissedPerTimes
FROM
base_treatment_process btp

    AND btp.appointment_id IS NOT NULL
    AND btp.appoint_status != 2
    AND btp.registered_id IS NULL
    AND CURRENT_DATE > btp.appoint_start_time

        AND btp.org_id IN

            #{item}




            AND DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d') >= #{query.startDate}


            AND DATE_FORMAT( btp.appoint_start_time, '%Y-%m-%d') <= #{query.endDate}




            AND DATE_FORMAT( btp.appoint_start_time, '%Y-%m') >= #{query.startDate}


            AND DATE_FORMAT( btp.appoint_start_time, '%Y-%m') <= #{query.endDate}




            AND DATE_FORMAT( btp.appoint_start_time, '%Y') >= #{query.startDate}


            AND DATE_FORMAT( btp.appoint_start_time, '%Y') <= #{query.endDate}



GROUP BY
btp.org_id
) btp6 ON bo.org_id = btp6.org_id
LEFT JOIN (
SELECT
bb.org_id,
SUM( bb.actual_amount ) AS totalActualAmount
FROM
base_bill bb

    AND bb.bill_date IS NOT NULL

        AND bb.org_id IN

            #{item}




            AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d') >= #{query.startDate}


            AND DATE_FORMAT( bb.bill_date, '%Y-%m-%d') <= #{query.endDate}




            AND DATE_FORMAT( bb.bill_date, '%Y-%m') >= #{query.startDate}


            AND DATE_FORMAT( bb.bill_date, '%Y-%m') <= #{query.endDate}




            AND DATE_FORMAT( bb.bill_date, '%Y') >= #{query.startDate}


            AND DATE_FORMAT( bb.bill_date, '%Y') <= #{query.endDate}



GROUP BY
bb.org_id
) bb ON bo.org_id = bb.org_id


        AND bo.org_id IN

            #{item}



GROUP BY
bo.org_id
